import {alignNodes} from './alignment.mjs';
import {LayoutStore,validateLayout,effectiveNodeState} from './layout-core.mjs';
const $=id=>document.getElementById(id), el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const blank={version:1,id:'untitled',name:'新建界面',canvas:{width:1672,height:941,background:'#19212b'},assets:[],nodes:[]};
async function database(){return new Promise((resolve,reject)=>{const r=indexedDB.open('layout-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('documents');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function readSaved(){const db=await database();try{return await new Promise((resolve,reject)=>{const r=db.transaction('documents').objectStore('documents').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}finally{db.close()}}
async function writeSaved(doc){const db=await database();try{await new Promise((resolve,reject)=>{const tx=db.transaction('documents','readwrite');tx.objectStore('documents').put(doc,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}finally{db.close()}}
let initial=blank;try{initial=validateLayout(await readSaved())}catch{try{initial=validateLayout(JSON.parse(localStorage.getItem('layout-studio-document')))}catch{}}
const store=new LayoutStore(initial);window.layoutStudio={store};let selectedIds=new Set();let zoom=.5,gesture=null,dirty=false,activeLayer=store.document.layers.find(l=>l.id==='buildings')?.id||store.document.layers[0].id;
const stage=$('stage'),wrap=$('stage-wrap');stage.style.overflow='visible';
const status=(s,error=false)=>{$('status').textContent=s;$('status').style.color=error?'#ffb0a5':''};
function safe(fn){return async(...args)=>{try{await fn(...args)}catch(e){status(e.message,true)}}}
function matrix(n){return new DOMMatrix().translate(n.x,n.y).rotate(n.rotation).scale(n.scaleX,n.scaleY).translate(-n.anchorX*n.width,-n.anchorY*n.height)}
function parentMatrix(n,doc){if(!n.parentId)return new DOMMatrix();const p=doc.nodes.find(x=>x.id===n.parentId);return parentMatrix(p,doc).multiply(matrix(p))}
function canvasPoint(e){const r=stage.getBoundingClientRect();return {x:(e.clientX-r.left)/zoom,y:(e.clientY-r.top)/zoom}}
function localPoint(p,n,doc){return parentMatrix(n,doc).inverse().transformPoint(p)}
function render(){const doc=store.document;if(!doc.layers.some(l=>l.id===activeLayer))activeLayer=doc.layers[0].id;stage.replaceChildren();stage.style.width=doc.canvas.width+'px';stage.style.height=doc.canvas.height+'px';stage.style.backgroundColor=doc.canvas.background;stage.style.transform=`scale(${zoom})`;stage.style.transformOrigin='0 0';stage.style.margin='32px';
 // Spacer reserves scaled canvas dimensions in the scroll surface.
 wrap.style.setProperty('--canvas-width',doc.canvas.width*zoom+'px');wrap.style.setProperty('--canvas-height',doc.canvas.height*zoom+'px');
 $('project-name').value=doc.name;$('canvas-width').value=doc.canvas.width;$('canvas-height').value=doc.canvas.height;$('zoom-label').textContent=Math.round(zoom*100)+'%';$('undo').disabled=!store.canUndo;$('redo').disabled=!store.canRedo;
 if($('grid-toggle').checked){stage.style.backgroundImage='linear-gradient(#ffffff16 1px,transparent 1px),linear-gradient(90deg,#ffffff16 1px,transparent 1px)';stage.style.backgroundSize='20px 20px'}else stage.style.backgroundImage='none';
 const ranks=new Map();for(const parent of new Set(doc.nodes.map(n=>n.parentId))){doc.nodes.filter(n=>n.parentId===parent).sort((a,b)=>doc.layers.find(l=>l.id===a.layerId).z-doc.layers.find(l=>l.id===b.layerId).z||a.z-b.z).forEach((n,i)=>ranks.set(n.id,i));}const map=new Map();for(const n of doc.nodes){const state=effectiveNodeState(doc,n);const box=el('div','scene-node');box.dataset.id=n.id;box.style.cssText=`position:absolute;left:${n.x}px;top:${n.y}px;width:${n.width}px;height:${n.height}px;transform:translate(${-n.anchorX*100}%,${-n.anchorY*100}%) rotate(${n.rotation}deg) scale(${n.scaleX},${n.scaleY});transform-origin:${n.anchorX*100}% ${n.anchorY*100}%;z-index:${ranks.get(n.id)};opacity:${n.opacity};display:${state.visible?'block':'none'};user-select:none;touch-action:none;pointer-events:${$('layer-edit-mode').checked&&n.layerId!==activeLayer?'none':'auto'};cursor:${state.locked||($('layer-edit-mode').checked&&n.layerId!==activeLayer)?'default':'move'};`;
 if(n.type==='image'){const img=el('img');img.src=doc.assets.find(a=>a.id===n.assetId)?.src||'';img.draggable=false;img.style.cssText='width:100%;height:100%;display:block;pointer-events:none;';box.append(img)}else{box.textContent=n.text;box.style.color='#e9b85a';box.style.fontSize=(n.height/2.2)+'px';box.style.fontFamily='KaiTi, serif';box.style.whiteSpace='pre-wrap';box.style.display=state.visible?'flex':'none';box.style.alignItems='center';box.style.justifyContent='center';box.style.textAlign='center'}
 box.addEventListener('pointerdown',e=>startGesture(e,n,'move'));map.set(n.id,box);}
 for(const n of doc.nodes)(map.get(n.parentId)||stage).append(map.get(n.id));
 for(const id of selectedIds){const n=doc.nodes.find(n=>n.id===id),box=map.get(id);if(n&&box&&effectiveNodeState(doc,n).visible)box.style.outline=`${2/zoom}px solid #58e2c6`;}const chosen=doc.nodes.find(n=>n.id===store.selectedId);if(chosen&&map.has(chosen.id)&&effectiveNodeState(doc,chosen).visible){const b=map.get(chosen.id);b.style.outline=`${2/zoom}px solid #58e2c6`;b.style.outlineOffset='2px';if(selectedIds.size===1&&!effectiveNodeState(doc,chosen).locked){for(const type of ['resize','rotate']){const h=el('button','transform-handle',type==='rotate'?'↻':'');h.title=type==='rotate'?'拖动旋转':'拖动调整宽高（Shift 保持比例）';h.dataset.handle=type;h.style.cssText=`position:absolute;width:${14/zoom}px;height:${14/zoom}px;padding:0;background:#b0fff0;border:1px solid #0d5348;border-radius:${type==='rotate'?'50%':'2px'};z-index:999999;${type==='rotate'?`left:50%;top:${-30/zoom}px;`:'right:0;bottom:0;'}cursor:${type==='rotate'?'grab':'nwse-resize'};`;h.onpointerdown=e=>startGesture(e,chosen,type);b.append(h)}}}
 if($('reference-toggle').checked){const ref=el('img');ref.src='/project-assets/reference.png';ref.alt='原始设计参考图';ref.style.cssText='position:absolute;inset:0;width:100%;height:100%;opacity:.45;pointer-events:none;z-index:2147483647';ref.onerror=()=>status('当前服务没有参考图，主城适配服务可提供参考图',true);stage.append(ref)}
 renderAlignment(doc);renderLayers(doc);renderList(doc);renderAssets(doc);if(!gesture)renderInspector(chosen,doc);
}
function selectNode(id,additive=false){if(additive){if(selectedIds.has(id))selectedIds.delete(id);else selectedIds.add(id)}else selectedIds=new Set(id?[id]:[]);store.select(selectedIds.size?(selectedIds.has(id)?id:[...selectedIds].at(-1)):null);}
function renderAlignment(doc){const eligible=[...selectedIds].filter(id=>{const n=doc.nodes.find(n=>n.id===id);return n&&effectiveNodeState(doc,n).visible&&!effectiveNodeState(doc,n).locked});$('selection-count').textContent=selectedIds.size?'已选 '+selectedIds.size+' 个元素':'未选中元素';for(const id of ['align-left','align-hcenter','align-right','align-top','align-vcenter','align-bottom','align-center'])$(id).disabled=!eligible.length;for(const id of ['distribute-h','distribute-v'])$(id).disabled=eligible.length<3;}
for(const [id,mode]of [['align-left','left'],['align-hcenter','hcenter'],['align-right','right'],['align-top','top'],['align-vcenter','vcenter'],['align-bottom','bottom'],['align-center','center'],['distribute-h','distribute-h'],['distribute-v','distribute-v']])$(id).onclick=safe(()=>{store.commit(alignNodes(store.document,[...selectedIds],mode,$('align-target').value));status('对齐完成（可撤销）');});
function renderLayers(doc){const host=$('layer-list');host.replaceChildren();const ordered=[...doc.layers].sort((a,b)=>b.z-a.z);for(const layer of ordered){const row=el('div','layer-row'+(layer.id===activeLayer?' active':''));row.dataset.layerId=layer.id;const name=el('button','layer-name',layer.name+' · '+doc.nodes.filter(n=>n.layerId===layer.id).length);name.onclick=()=>{activeLayer=layer.id;store.select(null);render();status('正在编辑：'+layer.name)};const eye=el('button','layer-eye',layer.visible?'◉':'○');eye.title='显示 / 隐藏整个图层';eye.onclick=()=>store.updateLayer(layer.id,{visible:!layer.visible});const lock=el('button','layer-lock',layer.locked?'🔒':'◇');lock.title='锁定 / 解锁整个图层';lock.onclick=()=>store.updateLayer(layer.id,{locked:!layer.locked});row.append(name,eye,lock);host.append(row)}$('active-layer-name').textContent=doc.layers.find(l=>l.id===activeLayer)?.name||'';}
$('add-layer').onclick=safe(()=>{const name=prompt('新图层名称','新图层');if(name){activeLayer=store.addLayer(name);store.select(null);render()}});
$('rename-layer').onclick=safe(()=>{const l=store.document.layers.find(l=>l.id===activeLayer),name=prompt('图层名称',l.name);if(name)store.updateLayer(l.id,{name})});
$('delete-layer').onclick=safe(()=>{const d=store.document,l=d.layers.find(l=>l.id===activeLayer);if(confirm('删除“'+l.name+'”及其中所有元素与关联子节点？（可撤销）'))store.deleteLayer(l.id)});
for(const [id,delta]of [['layer-up',1],['layer-down',-1]])$(id).onclick=safe(()=>{const d=store.document,ordered=[...d.layers].sort((a,b)=>a.z-b.z),i=ordered.findIndex(l=>l.id===activeLayer),j=Math.max(0,Math.min(ordered.length-1,i+delta));[ordered[i],ordered[j]]=[ordered[j],ordered[i]];ordered.forEach((l,k)=>d.layers.find(x=>x.id===l.id).z=k);store.commit(d)});
$('layer-edit-mode').onchange=render;
function renderList(doc){$('node-list').replaceChildren();const q=$('filter-nodes').value.trim().toLowerCase();for(const n of [...doc.nodes].filter(n=>n.layerId===activeLayer).sort((a,b)=>b.z-a.z)){if(!n.name.toLowerCase().includes(q))continue;const row=el('div','node-row'+(selectedIds.has(n.id)?' selected':''));row.dataset.nodeId=n.id;const name=el('button','node-name',n.name);name.style.cssText='flex:1;text-align:left;background:transparent;border:0;overflow:hidden;text-overflow:ellipsis';name.onclick=e=>selectNode(n.id,e.shiftKey||e.ctrlKey||e.metaKey);const eye=el('button','',n.visible?'◉':'○');eye.title='显示 / 隐藏';eye.onclick=()=>store.updateNode(n.id,{visible:!n.visible});const lock=el('button','',n.locked?'🔒':'◇');lock.title='锁定 / 解锁';lock.onclick=()=>store.updateNode(n.id,{locked:!n.locked});row.append(name,eye,lock);row.draggable=true;row.ondragstart=e=>e.dataTransfer.setData('text/layout-node',n.id);row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/layout-node');if(id&&id!==n.id){const ordered=[...doc.nodes].sort((a,b)=>a.z-b.z).filter(x=>x.id!==id);ordered.splice(ordered.findIndex(x=>x.id===n.id),0,doc.nodes.find(x=>x.id===id));const next=store.document;next.nodes=ordered.map((x,i)=>({...x,z:i}));store.commit(next)}};$('node-list').append(row)}}
function renderAssets(doc){$('asset-list').replaceChildren();for(const a of doc.assets){const b=el('button','asset-card');b.title='点击添加到画布';const img=el('img');img.src=a.src;img.style.cssText='width:100%;height:75px;object-fit:contain';b.append(img,el('span','',a.name));b.onclick=()=>store.addNode({id:crypto.randomUUID(),name:a.name,type:'image',layerId:activeLayer,assetId:a.id,x:doc.canvas.width/2,y:doc.canvas.height/2,width:a.width,height:a.height,z:Math.max(0,...doc.nodes.map(n=>n.z))+1});$('asset-list').append(b)}}
function renderInspector(n,doc){const host=$('inspector-fields');host.replaceChildren();if(selectedIds.size>1){host.append(el('div','section-intro','已选中 '+selectedIds.size+' 个元素'),el('p','asset-hint','使用上方对齐工具，Shift/Ctrl 点击可增减选择。'));return;}if(!n){host.append(el('p','empty-state','选择图层，拖动画布中的元素，或从素材库加入图片。'));return;}
 host.append(el('div','section-intro',n.type==='image'?'图像图层':'文字图层'));const id=el('p','asset-hint',n.id);id.style.wordBreak='break-all';host.append(id);
 const add=(label,key,type='number',opts={})=>{const field=el('label','field');field.append(el('span','',label));const input=el('input');input.type=type;input.dataset.property=key;if(type==='checkbox')input.checked=n[key];else input.value=n[key];if(type==='number'){input.step=opts.step||'1';if(opts.min!==undefined)input.min=opts.min;if(opts.max!==undefined)input.max=opts.max;}input.disabled=effectiveNodeState(doc,n).locked&&!['locked','visible','name'].includes(key);input.onchange=safe(()=>{const val=type==='checkbox'?input.checked:type==='number'?Number(input.value):input.value;store.updateNode(n.id,{[key]:val});status(label+'已更新')});field.append(input);host.append(field)};
 add('图层名称','name','text');if(n.type==='text')add('文字内容','text','text');for(const [label,key]of [['横坐标 X','x'],['纵坐标 Y','y'],['宽度','width'],['高度','height'],['旋转角度 °','rotation'],['水平缩放','scaleX'],['垂直缩放','scaleY'],['层级 Z','z'],['透明度','opacity'],['锚点 X','anchorX'],['锚点 Y','anchorY']])add(label,key,'number',{step:['scaleX','scaleY','opacity','anchorX','anchorY'].includes(key)?.05:1});add('显示图层','visible','checkbox');add('锁定图层','locked','checkbox');
 const membership=el('label','field');membership.append(el('span','','所属图层'));const layerSelect=el('select');layerSelect.dataset.property='layerId';for(const l of doc.layers)layerSelect.append(new Option(l.name,l.id));layerSelect.value=n.layerId;layerSelect.onchange=safe(()=>{const id=layerSelect.value;store.moveNodeToLayer(n.id,id);activeLayer=id;render()});membership.append(layerSelect);host.append(membership);const parent=el('label','field');parent.append(el('span','','父图层'));const select=el('select');select.append(new Option('画布根节点',''));for(const p of doc.nodes)if(p.id!==n.id)select.append(new Option(p.name,p.id));select.value=n.parentId||'';select.onchange=safe(()=>store.updateNode(n.id,{parentId:select.value||null}));parent.append(select);host.append(parent);
 const row=el('div','field-row');for(const [label,delta]of [['下移一层',-1],['上移一层',1]]){const b=el('button','',label);b.onclick=()=>{const d=store.document,ordered=d.nodes.filter(x=>x.parentId===n.parentId).sort((a,b)=>a.z-b.z),i=ordered.findIndex(x=>x.id===n.id),j=Math.max(0,Math.min(ordered.length-1,i+delta));[ordered[i],ordered[j]]=[ordered[j],ordered[i]];ordered.forEach((x,k)=>{d.nodes.find(y=>y.id===x.id).z=k});store.commit(d)};row.append(b)}host.append(row);
}
function startGesture(e,n,type){if(e.button!==0||($('layer-edit-mode').checked&&n.layerId!==activeLayer))return;e.stopPropagation();e.preventDefault();if(type==='move'&&(e.shiftKey||e.ctrlKey||e.metaKey)){selectNode(n.id,true);return;}selectNode(n.id);if(effectiveNodeState(store.document,n).locked){status('当前图层或元素已锁定');return;}const doc=store.document,p=localPoint(canvasPoint(e),n,doc);store.beginTransaction();gesture={id:n.id,type,start:p,node:{...n},doc};window.addEventListener('pointermove',moveGesture);window.addEventListener('pointerup',endGesture,{once:true});}
function moveGesture(e){if(!gesture)return;const g=gesture,n=g.node,p=localPoint(canvasPoint(e),n,g.doc);let patch={};if(g.type==='move'){let x=n.x+p.x-g.start.x,y=n.y+p.y-g.start.y;if($('snap-toggle').checked&&!e.altKey){x=Math.round(x/5)*5;y=Math.round(y/5)*5}patch={x,y};}else if(g.type==='rotate'){patch={rotation:n.rotation+(Math.atan2(p.y-n.y,p.x-n.x)-Math.atan2(g.start.y-n.y,g.start.x-n.x))*180/Math.PI};if(e.shiftKey)patch.rotation=Math.round(patch.rotation/15)*15;}else{const rad=-n.rotation*Math.PI/180,dx=p.x-g.start.x,dy=p.y-g.start.y;let width=Math.max(5,n.width+(dx*Math.cos(rad)-dy*Math.sin(rad))/n.scaleX),height=Math.max(5,n.height+(dx*Math.sin(rad)+dy*Math.cos(rad))/n.scaleY);if(e.shiftKey)height=width*n.height/n.width;const dw=(width-n.width)*n.anchorX*n.scaleX,dh=(height-n.height)*n.anchorY*n.scaleY,a=n.rotation*Math.PI/180;patch={width,height,x:n.x+dw*Math.cos(a)-dh*Math.sin(a),y:n.y+dw*Math.sin(a)+dh*Math.cos(a)}}store.updateNode(g.id,patch);status('正在'+({move:'移动',resize:'缩放',rotate:'旋转'}[g.type])+' · 松开鼠标完成');}
function endGesture(){window.removeEventListener('pointermove',moveGesture);gesture=null;store.endTransaction();status('变换完成，可撤销');}
stage.addEventListener('pointerdown',e=>{if(e.target===stage)store.select(null)});
let lastDocument=JSON.stringify(store.document);store.subscribe(({document:doc,selectedId})=>{selectedIds=new Set([...selectedIds].filter(id=>doc.nodes.some(n=>n.id===id)));if(selectedId===null)selectedIds.clear();else if(!selectedIds.has(selectedId))selectedIds=new Set([selectedId]);const signature=JSON.stringify(doc);if(signature!==lastDocument)dirty=true;lastDocument=signature;render()});
function fit(){const d=store.document;zoom=Math.min((wrap.clientWidth-80)/d.canvas.width,(wrap.clientHeight-80)/d.canvas.height);zoom=Math.max(.05,Math.min(2,zoom));render()}
$('zoom-in').onclick=()=>{zoom=Math.min(4,zoom*1.2);render()};$('zoom-out').onclick=()=>{zoom=Math.max(.05,zoom/1.2);render()};$('fit-view').onclick=fit;for(const id of ['grid-toggle','reference-toggle'])$(id).onchange=render;$('filter-nodes').oninput=()=>renderList(store.document);
$('undo').onclick=()=>store.undo();$('redo').onclick=()=>store.redo();$('duplicate-node').onclick=safe(()=>{if(store.selectedId)store.duplicateNode(store.selectedId)});$('delete-node').onclick=safe(()=>{if(store.selectedId)store.deleteNode(store.selectedId)});
$('project-name').onchange=()=>{const d=store.document;d.name=$('project-name').value||'未命名界面';store.commit(d)};for(const [id,key]of [['canvas-width','width'],['canvas-height','height']])$(id).onchange=safe(()=>{const d=store.document;d.canvas[key]=Number($(id).value);store.commit(d);fit()});
for(const tab of ['hierarchy','assets'])$('tab-'+tab).onclick=()=>{for(const t of ['hierarchy','assets']){$(t+'-panel').hidden=t!==tab;$('tab-'+t).classList.toggle('active',t===tab)}};
$('save-layout').onclick=safe(async()=>{await writeSaved(store.document);dirty=false;status('布局已保存到此浏览器（IndexedDB）')});
async function upgradeCityDocument(doc){const old=doc.nodes.find(n=>n.id==='Art_hud-bottom');if(doc.id!=='city'||!old)return doc;const r=await fetch('/api/projects/city');if(!r.ok)throw Error('旧版底栏需连接主城服务完成拆分迁移');const fresh=validateLayout(await r.json()),parts=fresh.nodes.filter(n=>n.id.startsWith('Art_hud-nav-')),rad=old.rotation*Math.PI/180,sx=old.width/900*old.scaleX,sy=old.height/176*old.scaleY;const nodes=parts.map((n,i)=>{const dx=(n.x-450)*sx,dy=(n.y-853)*sy;return {...n,x:old.x+dx*Math.cos(rad)-dy*Math.sin(rad),y:old.y+dx*Math.sin(rad)+dy*Math.cos(rad),scaleX:sx,scaleY:sy,rotation:old.rotation,z:old.z+i*.01,visible:old.visible,locked:old.locked,opacity:old.opacity,layerId:old.layerId}});const ids=new Set(parts.map(n=>n.assetId));return validateLayout({...doc,assets:[...doc.assets.filter(a=>a.id!=='hud-bottom'),...fresh.assets.filter(a=>ids.has(a.id))],nodes:[...doc.nodes.filter(n=>n.id!==old.id),...nodes]});}
async function loadCity(){const response=await fetch('/api/projects/city');if(!response.ok)throw Error('主城服务不可用，请使用附带 Node 服务；独立部署可通过导入 JSON 使用');const data=await response.json();store.setDocument(data.layout||data);fit();status('已加载主城工程 · 所有修改在应用前均为草稿')}
$('load-demo').onclick=safe(loadCity);
$('apply-layout').onclick=safe(async()=>{const payload=store.document;const baseResponse=await fetch('/api/projects/city');if(!baseResponse.ok)throw Error('主城适配服务不可用');const baseline=await baseResponse.json();const canonical=new Map(baseline.assets.map(a=>[a.id,a]));for(const a of payload.assets)if(canonical.has(a.id))a.src=canonical.get(a.id).src;const r=await fetch('/api/projects/city/layout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await r.json();if(!r.ok)throw Error(result.error||'写入失败');status('布局已写入主城工程，重新编译后生效');});
$('import-json').onclick=()=>$('file-json').click();$('file-json').onchange=safe(async e=>{const f=e.target.files[0];if(!f)return;store.setDocument(await upgradeCityDocument(validateLayout(JSON.parse(await f.text()))));fit();status('布局已导入');e.target.value=''});
async function dataURL(blob){return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(blob)})}
$('export-json').onclick=safe(async()=>{status('正在打包布局与图片…');const d=store.document;for(const a of d.assets)if(!a.src.startsWith('data:')){const r=await fetch(a.src);if(!r.ok)throw Error('素材打包失败：'+a.name);a.src=await dataURL(await r.blob())}const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=d.id+'.layout.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('已导出包含图片的可移植 JSON')});
$('add-image').onclick=()=>$('file-image').click();$('file-image').onchange=safe(async e=>{for(const f of e.target.files){if(!/^image\/(png|jpeg|webp|gif)$/.test(f.type))throw Error('请选择 PNG / JPG / WebP / GIF 图片');if(f.size>15*1024*1024)throw Error('单图请小于15MB');const src=await dataURL(f),img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src=src});const d=store.document,id=crypto.randomUUID();d.assets.push({id,name:f.name,src,width:img.naturalWidth,height:img.naturalHeight});store.commit(d);store.addNode({id:crypto.randomUUID(),name:f.name,type:'image',layerId:activeLayer,assetId:id,x:d.canvas.width/2,y:d.canvas.height/2,width:img.naturalWidth,height:img.naturalHeight,z:Math.max(0,...d.nodes.map(n=>n.z))+1});}e.target.value='';status('图片已加入素材库与画布')});
window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?store.redo():store.undo()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();store.redo()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();if(store.selectedId)store.duplicateNode(store.selectedId)}else if(e.key==='Delete'){if(store.selectedId)store.deleteNode(store.selectedId)}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&store.selectedId){e.preventDefault();const n=store.document.nodes.find(n=>n.id===store.selectedId);if(!effectiveNodeState(store.document,n).locked&&(!$('layer-edit-mode').checked||n.layerId===activeLayer))store.updateNode(n.id,{x:n.x+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0)*(e.shiftKey?10:1),y:n.y+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0)*(e.shiftKey?10:1)})}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});render();requestAnimationFrame(fit);if(!initial.nodes.length)safe(loadCity)();else if(initial.nodes.some(n=>n.id==='Art_hud-bottom'))safe(async()=>{store.setDocument(await upgradeCityDocument(store.document));fit();status('旧版布局已迁移为独立导航元素，请保存更新')})();
